UPDATE public.email_config
SET corpo_html = '<div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;padding:20px;"><div style="text-align:center;padding:30px 0;background:linear-gradient(135deg,{{cor_primaria}},#1a1a2e);border-radius:12px;"><h1 style="color:white;margin:0;font-size:24px;">{{nome_empresa}}</h1></div><div style="padding:30px 20px;"><h2 style="color:#333;">Bem-vindo(a) à equipe!</h2><p style="color:#666;line-height:1.6;">Você foi convidado(a) para fazer parte da equipe <strong>{{nome_empresa}}</strong>.</p><div style="text-align:center;padding:20px 0;"><a href="{{link_login}}" style="background:{{cor_primaria}};color:white;padding:14px 32px;border-radius:8px;text-decoration:none;font-weight:bold;">Acessar o Sistema</a></div><div style="text-align:center;padding:0 0 20px;"><a href="{{link_definir_senha}}" style="background:transparent;color:{{cor_primaria}};padding:12px 28px;border-radius:8px;text-decoration:none;font-weight:bold;border:2px solid {{cor_primaria}};">Definir Minha Senha</a></div></div></div>'
WHERE tipo = 'convite_usuario'
AND corpo_html NOT LIKE '%link_definir_senha%';